INSERT INTO `tbl_config_default` (`configid`, `configtype`, `attribute`, `value`) VALUES
(1, 'config', 'token', '6a66924e80a00df348bf7b4e6e68c1e6ebd69524'),
(2, 'config', 'companyname', 'Company Name'),
